function recordBatch(batch){for(const a of batch.answers||[]){if(a.selected?.length&&!a.isCorrect&&!a.solutionPreviouslyRevealed)meta(a.questionId).mistakes++;if(a.selected?.length)window.MADAR_ACTIVITY?.emit('quiz_check',{lesson:'network-srwe-'+a.questionId[0],question:'network-srwe-'+a.questionId,value:a.isCorrect?'correct':'incorrect'});}state.history.push({...batch,eventId:crypto.randomUUID()});}
function hydrateExtra(data,clean){
 if(data.location!=null&&!(typeof data.location==='string'&&/^(study-controls|q-[456]-\d\d|page-\d{1,2})$/.test(data.location)))throw Error('موضع قراءة غير صالح.');
 if(!clean.history.every(h=>h&&typeof h==='object'&&typeof h.event==='string'&&h.event.length<=40&&(!h.questionId||byId.has(h.questionId))&&(!h.answers||Array.isArray(h.answers)&&h.answers.length<=84&&h.answers.every(a=>byId.has(a.questionId)&&Array.isArray(a.selected)&&a.selected.every(s=>typeof s==='string'&&s.length===1&&'ABCD'.includes(s))))))throw Error('سجل محاولات غير صالح.');
 clean.meta={};clean.location=typeof data.location==='string'?data.location:null;
 for(const [id,m] of Object.entries(data.meta||{})){if(!byId.has(id)||!m||!Number.isInteger(m.mistakes)||m.mistakes<0||m.mistakes>100000||typeof m.marked!=='boolean'||typeof m.note!=='string'||m.note.length>6000)throw Error('علامة أو عداد أو ملاحظة غير صالحة.');clean.meta[id]={mistakes:m.mistakes,marked:m.marked,note:m.note};}
 if(!data.meta){for(const h of clean.history)for(const a of h.answers||[]){if(byId.has(a.questionId)&&a.selected?.length&&a.isCorrect===false&&!a.solutionPreviouslyRevealed){clean.meta[a.questionId]??={mistakes:0,marked:false,note:''};clean.meta[a.questionId].mistakes++;}}}
 return clean;
}
